// Sprite art, Saigon environment, separate side-view duel and noninteractive epilogue.
const characterSheet=new Image(),saigonStreet=new Image();let sheetReady=false,streetReady=false;
characterSheet.onload=()=>{sheetReady=true};characterSheet.src='assets/vy-sprites.png';saigonStreet.onload=()=>streetReady=true;saigonStreet.src='assets/saigon-street.png';
let duelStarted=false,duelPhase='intro',duelTimer=2.2,duelHP=100,duelClock=0,duelCooldown=0,guardUntil=0,dodgeUntil=0,punchUntil=0,impactUntil=0,epilogue=-1,duelHit=false,guardCount=0;
const previousStart=start,previousMove=move,previousAct=act,fallbackDraw=runnerDraw,fallbackCharacter=runner;
start=function(){duelStarted=false;duelPhase='intro';duelTimer=2.2;duelHP=100;duelClock=duelCooldown=guardUntil=dodgeUntil=punchUntil=impactUntil=guardCount=0;epilogue=-1;duelHit=false;$('action').disabled=false;$('left').textContent='←';$('right').textContent='→';$('controls').hidden=false;previousStart()};
move=function(d){if(mode!==2){previousMove(d);return}if(!playing||paused||epilogue>=0)return;if(d<0){dodgeUntil=duelClock+.7;beep(370,.06)}else{guardUntil=duelClock+.8;beep(240,.06)}};
act=function(){if(mode!==2){previousAct();return}if(!playing||paused||epilogue>=0||duelCooldown>0||duelPhase==='intro')return;punchUntil=duelClock+.3;duelCooldown=.45;beep(600,.08);if(duelPhase==='open'){duelHP=Math.max(0,duelHP-25);impactUntil=duelClock+.3;duelPhase='recover';duelTimer=.8;toast(duelHP?'Phản công trúng! Tên là khôn, nhưng chọn sai đối thủ.':'Đã tiễn một chiếc răng. Vẫn giữ nguyên phong độ.',2);if(!duelHP){epilogue=0;bossWon=true;$('controls').hidden=true;$('chapterTitle').textContent='Đường tới ánh sáng.';$('chapter').textContent='THE FINAL SCENE / CHỈ CẦN THẢ LỎNG';stopClip();$('bubble').hidden=true;beep(784,.3)}}else toast('Đợi boss ra đòn, né hoặc đỡ rồi phản công khi nó hở!',1.5)};
$('action').onclick=()=>act();$('left').onclick=()=>move(-1);$('right').onclick=()=>move(1);
frame=function(t){if(mode!==2){runnerFrame(t);return}if(!playing)return;const dt=last?Math.min((t-last)/1000,.04):0;last=t;if(!duelStarted){duelStarted=true;objects=[];rain=flood=0;stopClip();$('chapterTitle').textContent='Đấu trường: Vy vs. Răng Khôn';$('instruction').textContent='← Né · → Đỡ · Space / chạm Đánh để phản công';$('left').textContent='Né ↶';$('right').textContent='Đỡ ◇';$('action').textContent='Đánh ✦';toast('Boss chặn lối. Né hoặc đỡ đòn, rồi phản công lúc nó sơ hở.',4)}
if(!paused){elapsed+=dt;duelClock+=dt;duelCooldown=Math.max(0,duelCooldown-dt);if(epilogue>=0){epilogue+=dt;distance=1170+Math.min(1,epilogue/23)*540;if(epilogue>=24){distance=1710;finish();$('controls').hidden=false;return}}else{duelTimer-=dt;if(duelTimer<=0){if(duelPhase==='intro'||duelPhase==='recover'){duelPhase='windup';duelTimer=1.3;duelHit=false;toast('Boss lấy đà… chuẩn bị né hoặc đỡ!',1.2)}else if(duelPhase==='windup'){duelPhase='strike';duelTimer=.38;if(duelClock<dodgeUntil||duelClock<guardUntil){guardCount++;beep(800,.1);toast('Đỡ đẹp! Boss hở rồi — phản công!',2)}else{duelHit=true;bossHits++;impactUntil=duelClock+.3;beep(150,.15);toast('Áo giáp sinh nhật đã đỡ giúp. Vy vẫn đứng vững!',2)}}else if(duelPhase==='strike'){duelPhase='open';duelTimer=2.3}else{duelPhase='recover';duelTimer=.6}}}if(elapsed>toastUntil)$('bubble').hidden=true}
if(noiseGain)noiseGain.gain.value=0;draw();$('distance').textContent=epilogue>=0?'ĐƯỜNG TỚI SINH NHẬT':`BOSS · ${duelHP}/100`;$('progress').style.width=distance/1710*100+'%';$('threat').textContent=epilogue>=0?'Đoạn phim cuối · không cần điều khiển':'ĐẤU TRƯỜNG · NÉ / ĐỠ / PHẢN CÔNG';$('action').disabled=paused||duelCooldown>0;raf=requestAnimationFrame(frame)};
function coverImage(img,w,h){const r=Math.max(w/img.width,h*.7/(img.height*.586),h*.3/(img.height*.414));ctx.drawImage(img,(w-img.width*r)/2,h*.3-img.height*.414*r,img.width*r,img.height*r)}
function sprite(cell,x,y,height,flip=false,angle=0){if(!sheetReady){fallbackCharacter(x,y,height/120);return}const cw=characterSheet.width/4,ch=characterSheet.height/2;ctx.save();ctx.translate(x,y);ctx.rotate(angle);if(flip)ctx.scale(-1,1);const width=height*cw/ch;ctx.drawImage(characterSheet,(cell%4)*cw,Math.floor(cell/4)*ch,cw,ch,-width/2,-height,width,height);ctx.restore()}
runner=function(x,y,s=1,chaser=false){if(chaser){fallbackCharacter(x,y,s,true);return}sprite(Math.floor(elapsed*7)%2,x,y+19,185*s)};
function streetBackdrop(w,h){if(streetReady)coverImage(saigonStreet,w,h);else{ctx.fillStyle='#1c3343';ctx.fillRect(0,0,w,h)}const shade=ctx.createLinearGradient(0,0,0,h);shade.addColorStop(0,'#0b192b25');shade.addColorStop(1,'#07162644');ctx.fillStyle=shade;ctx.fillRect(0,0,w,h)}
draw=function(){if(mode===2){if(epilogue>=0)drawEpilogue();else drawDuel();return}drawSaigonRun()};
function drawSaigonRun(){const w=canvas.clientWidth,h=canvas.clientHeight;if(!streetReady){fallbackDraw();return}streetBackdrop(w,h);const hy=h*.3;ctx.globalAlpha=.27+flood*.4;poly([[w*.44,hy],[w*.56,hy],[w*1.05,h],[-w*.05,h]],flood>.3?'#2d7084':'#293941');ctx.globalAlpha=1;
for(let i=0;i<20;i++){const z=(i/20+elapsed*.24)%1;for(let l of [.5,1.5]){const p=project(l,z,w,h),q=project(l,Math.max(0,z-.025),w,h);ctx.strokeStyle=flood>.3?'#d0e6df44':'#f4e7cb88';ctx.lineWidth=1+p.p*3;ctx.beginPath();ctx.moveTo(p.x,p.y);ctx.lineTo(q.x,q.y);ctx.stroke()}}
// Parallax sidewalks carry street-specific signs, awnings and parked scooters.
for(let i=0;i<7;i++){const z=(i/7+elapsed*.052)%1,p=project(i%2?-1.3:3.3,z,w,h);ctx.save();ctx.translate(p.x,p.y);ctx.scale(p.s,p.s);ctx.fillStyle='#435b58';ctx.fillRect(-3,-125,6,125);ctx.fillStyle=i%2?'#9b664f':'#456d67';ctx.fillRect(-48,-120,96,37);text(['CÀ PHÊ','BÁNH MÌ','HỦ TIẾU','SÀI GÒN'][i%4],0,-97,10,'#f8e9cd');ctx.font='34px "Segoe UI Emoji"';ctx.textAlign='center';ctx.fillText('🛵',0,-4);ctx.restore()}
for(let i=0;i<3;i++){const x=w*(.15+i*.35),y=h+65-pressure*85;fallbackCharacter(x,y,.8,true);text(['DEADLINE','DỰ ÁN','CUỘC HỌP'][i],x,y-94,9,'#ffd0b7')}
for(const o of [...objects].sort((a,b)=>b.z-a.z)){if(o.z<0)continue;const p=project(o.lane,o.z,w,h);ctx.save();ctx.translate(p.x,p.y);ctx.scale(p.s,p.s);poly([[-29,0],[29,0],[29,-57],[-29,-57]],'#c9a777');poly([[29,0],[39,-9],[39,-67],[29,-57]],'#80664d');poly([[-29,-57],[29,-57],[39,-67],[-19,-67]],'#efdab5');text(mode===1?'SLIDE NỔI':['DEADLINE','DỰ ÁN','HỌP TIẾP'][o.type],0,-30,8,'#24343b');text('+5 PHÚT',0,-13,8,'#24343b');ctx.restore()}
const p=project(visualLane,.1,w,h);if(mode===1){ctx.save();ctx.translate(p.x,p.y);poly([[0,28],[-42,-4],[-32,-80],[0,-110],[32,-80],[42,-4]],'#d0a16d');poly([[0,15],[-29,-9],[-22,-69],[0,-90],[22,-69],[29,-9]],'#685044');sprite(0,0,-12,155);ctx.strokeStyle='#e6bf8f';ctx.lineWidth=5;ctx.beginPath();ctx.moveTo(-17,-55);ctx.lineTo(55+Math.sin(elapsed*6)*10,4);ctx.stroke();text('PHƯƠNG ÁN B',0,13,6,'#22313a');ctx.restore()}else sprite(Math.floor(elapsed*7)%2,p.x,p.y+18-jump*.6,190);
if(rain>0){ctx.fillStyle=`rgba(7,23,36,${rain*.25})`;ctx.fillRect(0,0,w,h);ctx.strokeStyle=`rgba(198,222,231,${rain*.65})`;ctx.lineWidth=1;for(let i=0;i<140*rain;i++){const x=(i*83+elapsed*180)%w,y=(i*61+elapsed*530)%h;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x-7,y+19);ctx.stroke()}}}
function drawDuel(){const w=canvas.clientWidth,h=canvas.clientHeight;streetBackdrop(w,h);ctx.fillStyle='#071422aa';ctx.fillRect(0,0,w,h);const ground=h*.8;ctx.fillStyle='#2d3941';ctx.fillRect(0,ground,w,h-ground);ctx.strokeStyle='#b89b6c88';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(0,ground);ctx.lineTo(w,ground);ctx.stroke();text('BẾN ĐỖ CUỐI · ĐẤU TRƯỜNG RĂNG KHÔN',w/2,h*.12,10,'#dfb77c');const bw=w*.7;ctx.fillStyle='#ffffff22';ctx.fillRect(w*.15,h*.17,bw,9);ctx.fillStyle='#e0b577';ctx.fillRect(w*.15,h*.17,bw*duelHP/100,9);text(`RĂNG KHÔN · ${duelHP}/100`,w/2,h*.17+28,11);
let cell=duelClock<punchUntil?3:duelClock<guardUntil?4:2;let px=w*.25-(duelClock<dodgeUntil?w*.1:0);sprite(cell,px,ground+15,Math.min(255,h*.47));if(duelClock<guardUntil){ctx.strokeStyle='#b0ded9';ctx.lineWidth=3;ctx.beginPath();ctx.arc(px+15,ground-85,63,-1.3,1.3);ctx.stroke()}
const bx=w*.73-(duelPhase==='strike'?w*.12:0);ctx.save();ctx.translate(bx,ground-50);ctx.scale(Math.min(w/300,1.6),Math.min(w/300,1.6));bossPhase=duelPhase==='open'?'exposed':'warning';bossFlash=duelClock<impactUntil?.2:0;drawTooth(0,0,1);ctx.restore();if(duelPhase==='windup'){text('!',bx,ground-160,35,'#ffb99d');text('Boss sắp ra đòn — né hoặc đỡ!',w/2,h*.92,11,'#e7b29e')}else text(duelPhase==='open'?'SƠ HỞ! PHẢN CÔNG NGAY':duelPhase==='intro'?'VY  VS.  RĂNG KHÔN':'Bình tĩnh. Chờ đúng lúc.',w/2,h*.92,12,duelPhase==='open'?'#f4d69f':'#c0ccce');if(duelClock<impactUntil){ctx.fillStyle='#fff0c51a';ctx.fillRect(0,0,w,h)}}
function drawEpilogue(){const w=canvas.clientWidth,h=canvas.clientHeight,t=epilogue;streetBackdrop(w,h);ctx.fillStyle='#07142588';ctx.fillRect(0,0,w,h);let subtitle='',cell=0,x=w/2,y=h*.85,size=210;
if(t<4){cell=Math.floor(t*7)%2;subtitle='Có những đoạn đường, Vy đã tự mình vượt qua.';for(let i=0;i<6;i++){const p=project(i%3,(i/6+t*.14)%1,w,h);ctx.strokeStyle='#93836d';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(p.x-20*p.s,p.y);ctx.lineTo(p.x,p.y-35*p.s);ctx.lineTo(p.x+20*p.s,p.y);ctx.stroke()}}
else if(t<8){cell=5;subtitle='Và có những lúc… chỉ muốn ngồi xuống một chút.';ctx.fillStyle='#07142566';ctx.fillRect(0,0,w,h)}
else if(t<13){cell=t<11?5:6;subtitle='Không sao. Hôm nay, có một ánh sáng chờ Vy phía trước.'}
else if(t<19){cell=Math.floor(t*7)%2;size=210-(t-13)*15;y=h*.85-(t-13)*h*.04;subtitle='Không cần bảo vệ kế hoạch. Không cần chạy thêm vì ai.'}
else{cell=7;size=200;subtitle='Chỉ cần đến đây. Và tận hưởng ngày của mình.'}
if(t>=8){const a=Math.min(1,(t-8)/3),g=ctx.createRadialGradient(w/2,h*.32,3,w/2,h*.32,h*.65);g.addColorStop(0,`rgba(255,233,177,${a*.9})`);g.addColorStop(.3,`rgba(232,187,110,${a*.25})`);g.addColorStop(1,'rgba(232,187,110,0)');ctx.fillStyle=g;ctx.fillRect(0,0,w,h);ctx.globalAlpha=a*.3;poly([[w*.47,h*.31],[w*.53,h*.31],[w*.76,h],[w*.24,h]],'#ffe0a0');ctx.globalAlpha=1;for(let i=0;i<23;i++){ctx.fillStyle='#ffe7b9';ctx.beginPath();ctx.arc(w*.3+(i*47%Math.max(1,w*.4)),h-((i*41+t*22)%h),1+i%2,0,7);ctx.fill()}}
sprite(cell,x,y,size);ctx.fillStyle='#0a1829cc';ctx.fillRect(0,h*.04,w,58);text(subtitle,w/2,h*.04+33,Math.max(9,Math.min(12,w/43)),'#f3dfbb');if(t>21){ctx.fillStyle=`rgba(248,231,199,${Math.min(1,(t-21)/3)})`;ctx.fillRect(0,0,w,h)}}
